head.b:skin:
/*
  Theme Name: SynFusion Blogger Premium Theme
  Author: SynFusion Agency (@getsynfusion)
  Tagline: We Build. We Innovate. We Scale.
*/
body {
  margin: 0;
  padding: 0;
  background-color: #ffffff;
  color: #17251E;
  font-family: 'Inter', system-ui, -apple-system, sans-serif;
}

body.script:
//
document.addEventListener('DOMContentLoaded', function() {
  // Set current copyright year
  var yearEl = document.getElementById('copyrightYear');
  if (yearEl) {
    yearEl.textContent = new Date().getFullYear();
  }

  // Toast notification helper
  function showToast(msg) {
    var toast = document.getElementById('toastNotification');
    var toastMsg = document.getElementById('toastMessage');
    if (toast && toastMsg) {
      toastMsg.textContent = msg;
      toast.style.display = 'flex';
      setTimeout(function() { toast.style.display = 'none'; }, 3000);
    }
  }

  // Mobile Navbar Menu Toggle
  var mobileToggle = document.getElementById('mobileToggle');
  var navLinks = document.getElementById('navLinks');
  if (mobileToggle && navLinks) {
    mobileToggle.addEventListener('click', function() {
      navLinks.classList.toggle('active');
    });
  }

  // -------------------------------------------------------------
  // AUTOMATIC GITHUB PORTFOLIO ENGINE (@devjeetx7-synfusion)
  // -------------------------------------------------------------
  var username = 'devjeetx7-synfusion';
  var allRepos = [];
  var filteredRepos = [];
  var currentPage = 1;
  var perPage = 6;

  var repoGrid = document.getElementById('githubRepoGrid');
  var searchInput = document.getElementById('repoSearchInput');
  var langSelect = document.getElementById('repoLangSelect');
  var sortSelect = document.getElementById('repoSortSelect');
  var forkToggle = document.getElementById('repoForkToggle');
  var refreshBtn = document.getElementById('repoRefreshBtn');
  var paginationContainer = document.getElementById('repoPaginationContainer');
  var profileBadgeContainer = document.getElementById('ghProfileBadgeContainer');

  // Fetch Profile Details
  fetch('https://api.github.com/users/' + username)
    .then(function(res) { if (res.ok) return res.json(); return null; })
    .then(function(user) {
      if (user && profileBadgeContainer) {
        profileBadgeContainer.innerHTML = "<div style='display: inline-flex; align-items: center; gap: 0.5rem; background: #ffffff; padding: 0.4rem 1rem; border-radius: 9999px; border: 1px solid var(--border-color); font-size: 0.8rem; font-weight: 700; shadow: var(--shadow-sm);'>" +
          "<span style='width: 8px; height: 8px; border-radius: 50%; background: #84CC16;'></span>" +
          "<span>GitHub: <a href='" + user.html_url + "' target='_blank' style='color: var(--primary);'>@" + user.login + "</a> (" + user.public_repos + " Public Repositories)</span>" +
          "</div>";
      }
    })
    .catch(function() {});

  function fetchGitHubRepos() {
    if (!repoGrid) return;
    repoGrid.innerHTML = "<div style='grid-column: 1 / -1; text-align: center; padding: 3rem 0; color: var(--text-muted);'>Fetching public GitHub repositories...</div>";

    // Check local caching
    var cacheTime = localStorage.getItem('synfusion_gh_time');
    var cachedRepos = localStorage.getItem('synfusion_gh_repos');
    if (cacheTime && cachedRepos && (Date.now() - parseInt(cacheTime, 10) < 600000)) {
      try {
        allRepos = JSON.parse(cachedRepos);
        populateLanguageDropdown();
        applyRepoFilters();
        return;
      } catch(e) {}
    }

    var fetchedRepos = [];
    function fetchPage(page) {
      return fetch('https://api.github.com/users/' + username + '/repos?per_page=100&sort=updated&page=' + page)
        .then(function(res) {
          if (!res.ok) throw new Error('Status ' + res.status);
          return res.json();
        })
        .then(function(pageRepos) {
          if (!Array.isArray(pageRepos) || pageRepos.length === 0) {
            return fetchedRepos;
          }
          fetchedRepos = fetchedRepos.concat(pageRepos);
          if (pageRepos.length === 100) {
            return fetchPage(page + 1);
          }
          return fetchedRepos;
        });
    }

    fetchPage(1)
      .then(function(data) {
        allRepos = data;
        try {
          localStorage.setItem('synfusion_gh_repos', JSON.stringify(data));
          localStorage.setItem('synfusion_gh_time', Date.now().toString());
        } catch(e) {}
        populateLanguageDropdown();
        applyRepoFilters();
      })
      .catch(function(err) {
        // Try reading stale cache
        if (cachedRepos) {
          try {
            allRepos = JSON.parse(cachedRepos);
            populateLanguageDropdown();
            applyRepoFilters();
            showToast('Using cached repository data.');
            return;
          } catch(e) {}
        }
        repoGrid.innerHTML = "<div style='grid-column: 1 / -1; text-align: center; padding: 3rem 0; color: #DC2626;'>Unable to load GitHub repositories. Please retry shortly.</div>";
      });
  }

  function populateLanguageDropdown() {
    if (!langSelect) return;
    var langs = new Set();
    allRepos.forEach(function(r) { if (r.language) langs.add(r.language); });
    langSelect.innerHTML = "<option value='All'>All Languages</option>";
    langs.forEach(function(l) {
      var opt = document.createElement('option');
      opt.value = l;
      opt.textContent = l;
      langSelect.appendChild(opt);
    });
  }

  function applyRepoFilters() {
    var query = searchInput ? searchInput.value.toLowerCase().trim() : '';
    var selectedLang = langSelect ? langSelect.value : 'All';
    var sortBy = sortSelect ? sortSelect.value : 'updated';
    var includeForks = forkToggle ? forkToggle.checked : false;

    filteredRepos = allRepos.filter(function(repo) {
      if (!includeForks && repo.fork) return false;
      if (selectedLang !== 'All' && repo.language !== selectedLang) return false;
      if (query !== '') {
        var nameMatch = repo.name.toLowerCase().includes(query);
        var descMatch = repo.description && repo.description.toLowerCase().includes(query);
        return nameMatch || descMatch;
      }
      return true;
    });

    // Sorting
    filteredRepos.sort(function(a, b) {
      if (sortBy === 'updated') return new Date(b.updated_at) - new Date(a.updated_at);
      if (sortBy === 'newest') return new Date(b.created_at) - new Date(a.created_at);
      if (sortBy === 'stars') return b.stargazers_count - a.stargazers_count;
      if (sortBy === 'name') return a.name.localeCompare(b.name);
      return 0;
    });

    currentPage = 1;
    renderRepoPage();
  }

  function renderRepoPage() {
    if (!repoGrid) return;
    if (filteredRepos.length === 0) {
      repoGrid.innerHTML = "<div style='grid-column: 1 / -1; text-align: center; padding: 3rem 0; color: var(--text-muted);'>No public repositories found matching your filters.</div>";
      if (paginationContainer) paginationContainer.innerHTML = '';
      return;
    }

    var start = (currentPage - 1) * perPage;
    var paged = filteredRepos.slice(start, start + perPage);

    var html = '';
    paged.forEach(function(repo) {
      var desc = repo.description || 'Public GitHub repository owned by SynFusion.';
      var lang = repo.language || 'Code';
      var stars = repo.stargazers_count || 0;
      var forks = repo.forks_count || 0;

      html += "<div class='gh-card'>";
      html += "  <div>";
      html += "    <div class='gh-repo-title'>";
      html += "      <a href='" + repo.html_url + "' target='_blank' style='color: var(--text-main);'>" + repo.name + "</a>";
      if (repo.fork) html += " <span style='font-size: 0.7rem; background: #e2e8f0; padding: 0.1rem 0.4rem; border-radius: 4px;'>Fork</span>";
      html += "    </div>";
      html += "    <div class='gh-repo-desc'>" + desc + "</div>";
      html += "  </div>";
      html += "  <div class='gh-meta'>";
      html += "    <span>&#9679; " + lang + "</span>";
      html += "    <span>&#9733; " + stars + " | &#9282; " + forks + "</span>";
      html += "    <a href='" + repo.html_url + "' target='_blank' style='color: var(--primary); font-weight: 700;'>Open Repo &#8594;</a>";
      html += "  </div>";
      html += "</div>";
    });

    repoGrid.innerHTML = html;
    renderPagination();
  }

  function renderPagination() {
    if (!paginationContainer) return;
    var totalPages = Math.ceil(filteredRepos.length / perPage);
    if (totalPages <= 1) {
      paginationContainer.innerHTML = '';
      return;
    }

    var html = '';
    for (var i = 1; i <= totalPages; i++) {
      var activeClass = (i === currentPage) ? 'btn-primary' : 'btn-outline';
      html += "<button class='btn btn-sm " + activeClass + "' onclick='changeRepoPage(" + i + ")'>" + i + "</button>";
    }
    paginationContainer.innerHTML = html;
  }

  window.changeRepoPage = function(page) {
    currentPage = page;
    renderRepoPage();
  };

  if (searchInput) searchInput.addEventListener('input', applyRepoFilters);
  if (langSelect) langSelect.addEventListener('change', applyRepoFilters);
  if (sortSelect) sortSelect.addEventListener('change', applyRepoFilters);
  if (forkToggle) forkToggle.addEventListener('change', applyRepoFilters);
  if (refreshBtn) refreshBtn.addEventListener('click', function() {
    localStorage.removeItem('synfusion_gh_repos');
    localStorage.removeItem('synfusion_gh_time');
    fetchGitHubRepos();
    showToast('Refreshing GitHub repositories...');
  });

  if (repoGrid) fetchGitHubRepos();

  // FAQ Accordion Toggle
  window.toggleFAQ = function(element) {
    var faqItem = element.parentElement;
    var isActive = faqItem.classList.contains('active');
    var allItems = document.querySelectorAll('.faq-item');
    allItems.forEach(function(item) { item.classList.remove('active'); });
    if (!isActive) {
      faqItem.classList.add('active');
    }
  };

  // -------------------------------------------------------------
  // POST READER ENHANCEMENTS (Progress, TOC, Code Copy, Sharing)
  // -------------------------------------------------------------
  var articleBody = document.getElementById('articleBodyContent');
  if (articleBody) {
    // 1. Reading Progress Bar
    window.addEventListener('scroll', function() {
      var progressBar = document.getElementById('readingProgressBar');
      if (!progressBar) return;
      var rect = articleBody.getBoundingClientRect();
      var totalHeight = articleBody.offsetHeight;
      var visibleTop = window.innerHeight - rect.top;
      var progress = Math.min(100, Math.max(0, (visibleTop / (totalHeight + window.innerHeight)) * 100));
      progressBar.style.width = progress + '%';
    });

    // 2. Table of Contents Generation
    var headings = articleBody.querySelectorAll('h2, h3');
    var tocBox = document.getElementById('postTocContainer');
    var tocList = document.getElementById('postTocList');

    if (headings.length > 0 && tocBox && tocList) {
      tocBox.style.display = 'block';
      headings.forEach(function(h, idx) {
        var id = h.id || 'heading-' + idx;
        h.id = id;
        var li = document.createElement('li');
        if (h.tagName.toLowerCase() === 'h3') li.style.paddingLeft = '1rem';
        li.innerHTML = "<a href='#" + id + "'>" + h.textContent + "</a>";
        tocList.appendChild(li);
      });
    }

    // 3. Formatted Code Blocks & Copy Code Button
    var codeBlocks = articleBody.querySelectorAll('pre');
    codeBlocks.forEach(function(pre) {
      var btn = document.createElement('button');
      btn.className = 'code-copy-btn';
      btn.textContent = 'Copy Code';
      btn.addEventListener('click', function() {
        var text = pre.textContent.replace('Copy Code', '');
        navigator.clipboard.writeText(text).then(function() {
          btn.textContent = 'Copied!';
          showToast('Code copied to clipboard.');
          setTimeout(function() { btn.textContent = 'Copy Code'; }, 2000);
        });
      });
      pre.appendChild(btn);
    });
  }

  // Article Sharing Helpers
  window.sharePostWhatsApp = function() {
    window.open('https://wa.me/?text=' + encodeURIComponent(document.title + ' ' + window.location.href), '_blank');
  };
  window.sharePostTelegram = function() {
    window.open('https://t.me/share/url?url=' + encodeURIComponent(window.location.href) + '&text=' + encodeURIComponent(document.title), '_blank');
  };
  window.sharePostFacebook = function() {
    window.open('https://www.facebook.com/sharer/sharer.php?u=' + encodeURIComponent(window.location.href), '_blank');
  };
  window.copyPostLink = function() {
    navigator.clipboard.writeText(window.location.href).then(function() {
      showToast('Article link copied to clipboard!');
    });
  };

  // Contact Form Handler
  window.handleContactSubmit = function(event) {
    event.preventDefault();
    var name = document.getElementById('contactName').value;
    var email = document.getElementById('contactEmail').value;
    var service = document.getElementById('contactService').value;
    var message = document.getElementById('contactMessage').value;
    var statusEl = document.getElementById('formStatusMessage');

    if (!name || !email || !service || !message) return;

    var encodedMsg = encodeURIComponent("Hi SynFusion Team,\n\nName: " + name + "\nEmail: " + email + "\nService: " + service + "\nDetails: " + message);
    var waUrl = "https://wa.me/919334603912?text=" + encodedMsg;

    if (statusEl) {
      statusEl.style.display = 'block';
      statusEl.style.color = '#008F4C';
      statusEl.textContent = 'Redirecting to WhatsApp with your inquiry...';
    }

    setTimeout(function() { window.open(waUrl, '_blank'); }, 1000);
  };
});
//
